//! Where a tuple lists a kind, for generic code to read a type out of an actor's handler list (ADR-0035).

use super::At;

/// The tuple lists `K` at `I`, its place, which the compiler infers.
///
/// Generic code reads a type parameter out of an actor's handler list with it: the bound `A::Handles: Lists<Inbound<In>,
/// I>` finds the one place whose kind matches, and with it `In`. The place is inferred, and never written. A pure
/// marker: nothing is read when the program runs.
///
/// ```
/// use aethereal_actor::{At, Lists};
/// use core::marker::PhantomData;
///
/// struct Inbound<In>(PhantomData<In>);
/// struct Outbound;
/// struct Shut;
/// struct Caller;
///
/// fn attached<L: Lists<Inbound<In>, I>, In, I>() -> PhantomData<(In, I)> {
///     PhantomData
/// }
///
/// let _found: PhantomData<(Caller, At<1>)> = attached::<(Outbound, Inbound<Caller>, Shut), _, _>();
/// ```
///
/// A tuple that lists two kinds that match is ambiguous, and does not build:
///
/// ```compile_fail
/// use aethereal_actor::Lists;
/// use core::marker::PhantomData;
///
/// struct Inbound<In>(PhantomData<In>);
/// struct Caller;
///
/// fn attached<L: Lists<Inbound<In>, I>, In, I>() -> PhantomData<(In, I)> {
///     PhantomData
/// }
///
/// let _found = attached::<(Inbound<()>, Inbound<Caller>), _, _>();
/// ```
///
/// A tuple holds up to 64, as [`HandledList`](super::HandledList)'s does, at a cost that grows with the square of its
/// length.
pub trait Lists<K, I> {}

macro_rules! tuples {
    ($( [$($name:ident $place:literal)*] )*) => {$(
        tuples!(@lists [$($name)*] $($name $place)*);
    )*};
    (@lists $all:tt $($name:ident $place:literal)*) => {$(
        tuples!(@list $all $name $place);
    )*};
    (@list [$($all:ident)*] $name:ident $place:literal) => {
        impl<$($all),*> Lists<$name, At<$place>> for ($($all,)*) {}
    };
}

